"""System prompt, output contract and regulatory texts for the Advisory Agent."""

from __future__ import annotations

import json
from typing import List

from pydantic import BaseModel, ConfigDict, Field

# --------------------------------------------------------------------------- #
# Mandatory disclaimers (appended deterministically, never generated by the LLM)
# --------------------------------------------------------------------------- #
LEGAL_DISCLAIMER = (
    "DebitMatch AI provides an informational comparison of publicly available product terms. "
    "It is not certified investment, tax or legal advice and does not constitute an offer by any "
    "financial institution. Verify current terms in the official RECA contract and with the bank "
    "before opening an account."
)
FRESHNESS_DISCLAIMER_TEMPLATE = (
    "Product data was last verified on {oldest_date}. Fees, rates and promotions can change at any "
    "time; data older than {max_age_days} days is treated as potentially outdated."
)
ABSTENTION_WARNING = (
    "ABSTENTION NOTICE: DebitMatch AI is withholding a definitive recommendation because {reasons}. "
    "The comparison below is provisional and must be re-validated before acting on it."
)
HITL_NOTICE = (
    "This case has been escalated for review by a human financial specialist before any final "
    "recommendation is issued. Reasons: {reasons}."
)
# Exact wording from "Multi-Agent Architecture and Coordination Plan V2", section 5.
FALLBACK_DISCLAIMER = (
    "Notice: Live API feeds unavailable. Recommendation generated using cached CONDUSEF baseline data. "
    "Verify current terms before opening."
)
# Exact wording from "RAG and Retrieval Design Integration V1", section 5 (abstention mechanism).
BENEFIT_UNVERIFIED_TEMPLATE = (
    "Our records indicate this benefit ({benefit}) was available for {product} as of {date}, but it does not appear "
    "in the current live catalog. We recommend verifying this directly with the bank before applying."
)
# Exact wording from "Tree-of-Thought Integration Plan V1", section 2.5 (timeout fallback).
TOT_TIMEOUT_NOTICE = (
    "We found a strong valid match, but additional options may exist. Would you like to explore further?"
)
MISSING_DEPOSIT_WARNING = (
    "No deposit or average balance was provided; figures assume an average balance of MXN 0.00. Fee waivers and "
    "interest depend on your balance, so please share it for an accurate comparison."
)
NEGOTIATION_INTRO = (
    "No product in the catalog satisfies all of your hard constraints. The closest alternatives below each require "
    "relaxing one or more constraints."
)
DETERMINISTIC_FIGURES_NOTE = (
    "All MXN amounts and rates were computed by the deterministic DebitMatch calculator from catalog "
    "data, including ISR withholding on interest where applicable."
)


class AdvisoryNarrative(BaseModel):
    """Structured narrative requested from the LLM. Numbers must come from the facts JSON."""

    model_config = ConfigDict(extra="forbid")

    summary: str = Field(description="Two to three sentences answering the user's request.")
    base_option_rationale: str = Field(description="Why the Base Option ($0 fee / risk-free) fits the user.")
    tradeoff_option_rationale: str = Field(
        description="Why the Positive Trade-off Option may earn more, or why no such option exists."
    )
    key_tradeoffs: List[str] = Field(description="Two to four bullet points comparing both options.")


ADVISORY_SYSTEM_PROMPT = json.dumps(
    {
        "role": "DebitMatch AI - Consultative Advisory Agent",
        "mission": (
            "Explain, transparently and neutrally, how the verified Base Option ($0 Fee / Risk-Free) "
            "compares with the Positive Trade-off Option (higher net annual return) for this user."
        ),
        "rules": [
            "Use ONLY facts from the verified_facts JSON. Never invent products, banks, rates, fees or perks.",
            "Copy any MXN amount or percentage exactly as it appears in verified_facts; never compute new numbers.",
            (
                "Make no claims about the catalog as a whole or about accounts that are not base_option or "
                "tradeoff_option. If tradeoff_option is null, say only that no Positive Trade-off Option was "
                "identified among the N accounts compared, where N is the value of accounts_compared (or, if "
                "comparison_completed is false, that the comparison did not finish); never say that no better "
                "account exists in the catalog or anywhere."
            ),
            (
                "Write for the user in plain English. Never write the names of verified_facts fields or any other "
                "identifier with underscores (e.g. accounts_compared, base_option, net_annual_impact_mxn) or a "
                "product_key; say 'the accounts compared', 'the Base Option', 'net annual impact' and use the "
                "official bank and product names."
            ),
            (
                "Do not state conditions that are absent from verified_facts (e.g. whether transfers are needed, "
                "eligibility, opening requirements); describe transfers only through monthly_transfers, "
                "preferred_channel and transfer_channel_used."
            ),
            (
                "If abstain is true, EVERY sentence must be provisional ('may', 'appears', 'based on data that may be "
                "outdated'); never state definitively that an option is best or that no better alternative exists."
            ),
            (
                "Explain trade-offs through the user's priorities in words (e.g. 'your priority on avoiding fees'); "
                "never quote the numeric preference weights or the archetype label."
            ),
            (
                "If an option has yield_rate_is_estimate = true, say that its yield rate is an estimate to be "
                "confirmed with the bank."
            ),
            (
                "Never use absolute or overconfident markers such as 'guaranteed', '100%', 'definitely', 'certainly', "
                "'no risk' or 'you will earn'; financial terms can change and the comparison is informational."
            ),
            (
                "Do not mention higher_balance_option or its account: a verified sentence about it is appended "
                "to key_tradeoffs automatically."
            ),
            "If conversation_context is present, take the user's earlier refinements into account.",
            "If reviewer_feedback is present, fix every listed issue in this revision.",
            "Do not include disclaimers; they are appended automatically.",
            "Keep official bank names exactly as provided. Respond in English only.",
        ],
        "input_format": {
            "user_query": "string",
            "verified_facts": ("object with base_option, tradeoff_option, higher_balance_option, "
                               "top_score_not_recommended, accounts_compared, comparison_completed, "
                               "higher_net_return_alternative_found, preferences, archetype, hard_constraints, "
                               "deposit_mxn, monthly_transfers, preferred_channel, abstain, abstention_reasons"),
            "reviewer_feedback": "list of issues from the previous review (may be empty)",
        },
        "output_contract": {
            "format": "strict JSON matching the provided schema, no prose outside JSON",
            "fields": ["summary", "base_option_rationale", "tradeoff_option_rationale", "key_tradeoffs"],
        },
    },
    indent=2,
)
